def download(remote_location, remotes=None, prefix="", dry_run=False):
    """
    Download resources from a stage server.
    """
    if remotes is None:
        remotes = {}

    if isinstance(remote_location, list):
        for loc in remote_location:
            download(loc, remotes, prefix, dry_run)
        return

