    # add the remote location to the prefix.
    if os.path.isabs(remote_location):
        remote_location = prefix + remote_location
    else:
        remote_location = prefix + os.path.join(prefix, remote_location)

    # If the remote location is a directory, we want to download
    # all the files in that directory.
    if os.path.isdir(remote_location):
        for root, dirs, files in os.walk(remote_location):
            for f in files:
                download(os.path.join(root, f), remotes, prefix, dry_run)
        return

    # If the remote location is a file, we want to download that
    # file.
    if os.path.isfile(remote_location):
        # Find the local location of the file.
        local_location = remotes.get(remote_location)

        if local_location is None:
            raise RuntimeError(
                "The file %s does not exist in the remotes mapping." %
                remote_location)

        # If the local location is a relative path, then we need to
        # add the remote location to the prefix.
        if os.path.isabs(local_location):
            local_location = prefix + local_location
